import { useEffect, useState, useCallback } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

function AdminCodesPanel({ auth }) {
  const [codes, setCodes] = useState([]);
  const [amount, setAmount] = useState(10);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);       // For fetch
  const [generating, setGenerating] = useState(false); // For generate button

  // Fetch codes (wrapped in useCallback for useEffect)
  const fetchCodes = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_URL}/api/admin/codes`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      setCodes(res.data);
    } catch {
      setMessage("Failed to fetch codes");
    } finally {
      setLoading(false);
    }
  }, [auth.token]);

  useEffect(() => {
    fetchCodes();
  }, [fetchCodes]);

  // Generate new codes
  const generateCodes = async () => {
    if (amount <= 0) {
      alert("Amount must be greater than 0");
      return;
    }

    setGenerating(true);
    try {
      const res = await axios.post(
        `${API_URL}/api/admin/generate-codes`,
        { amount },
        { headers: { Authorization: `Bearer ${auth.token}` } }
      );
      setMessage(res.data.message);
      fetchCodes();
    } catch {
      setMessage("Failed to generate codes");
    } finally {
      setGenerating(false);
    }
  };

  const copyCode = (code) => {
    navigator.clipboard.writeText(code);
    alert("Code copied: " + code);
  };

  return (
    <div style={{ marginTop: 40 }}>
      <h2>Voter Code Management</h2>

      {message && <div style={{ marginBottom: 15, color: "green" }}>{message}</div>}

      <div style={{ marginBottom: 20 }}>
        <input
          type="number"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          style={{ padding: 8, marginRight: 10 }}
          min="1"
        />
        <button onClick={generateCodes} disabled={generating}>
          {generating ? "Generating..." : "Generate Codes"}
        </button>
        <button onClick={fetchCodes} style={{ marginLeft: 10 }} disabled={loading}>
          {loading ? "Refreshing..." : "Refresh"}
        </button>
      </div>

      {loading ? (
        <p>Loading codes...</p>
      ) : (
        <table border="1" cellPadding="10" style={{ width: "100%" }}>
          <thead>
            <tr>
              <th>Code</th>
              <th>Used</th>
              <th>Voted</th>
              <th>Copy</th>
            </tr>
          </thead>
          <tbody>
            {codes.map((c) => (
              <tr key={c._id}>
                <td>{c.code}</td>
                <td>{c.used ? "Yes" : "No"}</td>
                <td>{c.voted ? "Yes" : "No"}</td>
                <td>
                  <button onClick={() => copyCode(c.code)}>Copy</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default AdminCodesPanel;
